from __future__ import annotations

from collections.abc import Mapping
from typing import Any

from .priority_contracts import ExecutivePriorityItem, PriorityBand


_TEXT_PRIORITY = {
    "CRITICA": PriorityBand.CRITICA,
    "CRITICAL": PriorityBand.CRITICA,
    "URGENTE": PriorityBand.ALTA,
    "ALTA": PriorityBand.ALTA,
    "HIGH": PriorityBand.ALTA,
    "MEDIA": PriorityBand.MEDIA,
    "MEDIUM": PriorityBand.MEDIA,
    "NORMAL": PriorityBand.MEDIA,
    "BAJA": PriorityBand.BAJA,
    "LOW": PriorityBand.BAJA,
}

_OPERATIONAL_SLA_PRIORITY = {
    "ESCALADA": PriorityBand.CRITICA,
    "VENCIDA": PriorityBand.CRITICA,
    "URGENTE": PriorityBand.ALTA,
    "ADVERTENCIA": PriorityBand.MEDIA,
}

_CRM_SLA_PRIORITY = {
    "VENCIDO": PriorityBand.CRITICA,
    "PROXIMO": PriorityBand.ALTA,
}


def _first(record: Mapping[str, Any], *keys: str) -> Any:
    for key in keys:
        value = record.get(key)
        if value not in (None, ""):
            return value
    return None


def _text(value: Any) -> str | None:
    if value in (None, ""):
        return None
    return str(value)


def _priority_from_text(value: Any) -> PriorityBand:
    normalized = str(value or "").strip().upper()
    return _TEXT_PRIORITY.get(normalized, PriorityBand.SIN_PRIORIDAD)


def _unique(values: tuple[str, ...]) -> tuple[str, ...]:
    return tuple(dict.fromkeys(value for value in values if value))


def _permissions(record: Mapping[str, Any]) -> tuple[str, ...]:
    raw = _first(record, "permission_refs", "permisos", "permissions")
    if raw is None:
        return ()
    if isinstance(raw, str):
        return (raw,)
    if isinstance(raw, (list, tuple, set)):
        return _unique(tuple(str(value) for value in raw if value not in (None, "")))
    return (str(raw),)


def adapt_operational_task(record: Mapping[str, Any]) -> ExecutivePriorityItem | None:
    task_id = _first(record, "id", "tarea_id", "TareaID", "TareaId")
    if task_id is None:
        return None

    sla_state = str(_first(record, "estado_sla", "EstadoSLA") or "").strip().upper() or None
    source_priority = _priority_from_text(_first(record, "prioridad", "Prioridad"))
    sla_priority = _OPERATIONAL_SLA_PRIORITY.get(sla_state or "")
    band = sla_priority or source_priority

    reasons: tuple[str, ...] = ()
    if sla_priority:
        reasons += (f"SLA_{sla_state}",)
    if source_priority is not PriorityBand.SIN_PRIORIDAD:
        reasons += (f"SOURCE_PRIORITY_{source_priority.value}",)
    if not reasons:
        reasons = ("NO_PRIORITY_SIGNAL",)

    return ExecutivePriorityItem(
        source_domain="OPERATIVO",
        source_object_ref=f"tarea:{task_id}",
        title=str(_first(record, "titulo", "Titulo", "descripcion", "Descripcion") or f"Tarea {task_id}"),
        priority_band=band,
        priority_score_explanation=_unique(reasons),
        sla_state=sla_state,
        due_at=_text(_first(record, "fecha_limite", "FechaLimite")),
        impact=_text(_first(record, "impacto", "Impacto")),
        owner_ref=_text(_first(record, "responsable_id", "ResponsableID", "usuario_responsable_id")),
        permission_refs=_permissions(record),
        as_of=_text(_first(record, "as_of", "fecha_actualizacion", "FechaActualizacion")),
        stale=bool(_first(record, "stale", "es_stale") or False),
    )


def adapt_crm_opportunity(record: Mapping[str, Any]) -> ExecutivePriorityItem | None:
    opportunity_id = _first(record, "OportunidadID", "oportunidad_id", "id")
    if opportunity_id is None:
        return None

    sla_state = str(_first(record, "EstatusSLA", "estatus_sla", "estado_sla") or "").strip().upper() or None
    source_priority = _priority_from_text(_first(record, "Prioridad", "prioridad"))
    sla_priority = _CRM_SLA_PRIORITY.get(sla_state or "")
    band = sla_priority or source_priority

    reasons: tuple[str, ...] = ()
    if sla_priority:
        reasons += (f"CRM_SLA_{sla_state}",)
    if source_priority is not PriorityBand.SIN_PRIORIDAD:
        reasons += (f"SOURCE_PRIORITY_{source_priority.value}",)
    if not reasons:
        reasons = ("NO_PRIORITY_SIGNAL",)

    amount = _first(record, "MontoEstimado", "monto_estimado")
    impact = f"monto_estimado:{amount}" if amount not in (None, "") else None

    return ExecutivePriorityItem(
        source_domain="CRM",
        source_object_ref=f"oportunidad:{opportunity_id}",
        title=str(_first(record, "Nombre", "NombreOportunidad", "nombre") or f"Oportunidad {opportunity_id}"),
        priority_band=band,
        priority_score_explanation=_unique(reasons),
        sla_state=sla_state,
        due_at=_text(_first(record, "fecha_limite", "FechaLimite")),
        impact=impact,
        owner_ref=_text(_first(record, "ResponsableID", "responsable_id")),
        permission_refs=_permissions(record),
        as_of=_text(_first(record, "as_of", "FechaUltimaActividad", "fecha_ultima_actividad")),
        stale=bool(_first(record, "stale", "es_stale") or False),
    )

from __future__ import annotations

from collections.abc import Iterable

from .priority_contracts import (
    ExecutivePriorityAggregate,
    ExecutivePriorityItem,
    PriorityBand,
)


_BAND_ORDER = {
    PriorityBand.CRITICA: 0,
    PriorityBand.ALTA: 1,
    PriorityBand.MEDIA: 2,
    PriorityBand.BAJA: 3,
    PriorityBand.SIN_PRIORIDAD: 4,
}


def _sort_key(item: ExecutivePriorityItem) -> tuple[int, int, str, str, str]:
    due_missing = 1 if not item.due_at else 0
    due_at = item.due_at or ""
    return (
        _BAND_ORDER[item.priority_band],
        due_missing,
        due_at,
        item.source_domain,
        item.source_object_ref,
    )


def aggregate_priorities(
    items: Iterable[ExecutivePriorityItem | None],
) -> ExecutivePriorityAggregate:
    accepted = tuple(item for item in items if item is not None)
    deduplicated: dict[tuple[str, str], ExecutivePriorityItem] = {}

    for item in accepted:
        key = (item.source_domain, item.source_object_ref)
        current = deduplicated.get(key)
        if current is None or _sort_key(item) < _sort_key(current):
            deduplicated[key] = item

    ordered = tuple(sorted(deduplicated.values(), key=_sort_key))
    domains = tuple(sorted({item.source_domain for item in ordered}))

    return ExecutivePriorityAggregate(
        items=ordered,
        total=len(ordered),
        domains=domains,
        stale=any(item.stale for item in ordered),
    )

from modules.bos_executive import (
    PriorityBand,
    adapt_crm_opportunity,
    adapt_operational_task,
    aggregate_priorities,
)


def test_e3b_operational_sla_reuses_existing_state_as_priority_signal():
    item = adapt_operational_task(
        {
            "id": "T-1",
            "titulo": "Revisar diferencia",
            "estado_sla": "VENCIDA",
            "prioridad": "MEDIA",
            "fecha_limite": "2026-09-19T08:00:00Z",
            "responsable_id": "user-1",
            "permission_refs": ["OPERATIVO_VER"],
        }
    )

    assert item is not None
    assert item.source_domain == "OPERATIVO"
    assert item.source_object_ref == "tarea:T-1"
    assert item.priority_band is PriorityBand.CRITICA
    assert "SLA_VENCIDA" in item.priority_score_explanation
    assert item.owner_ref == "user-1"
    assert item.permission_refs == ("OPERATIVO_VER",)


def test_e3b_crm_sla_adapter_normalizes_without_creating_task_lifecycle():
    item = adapt_crm_opportunity(
        {
            "OportunidadID": "OP-9",
            "Nombre": "Renovacion mayorista",
            "MontoEstimado": 250000,
            "EstatusSLA": "PROXIMO",
            "Prioridad": "BAJA",
            "ResponsableID": "crm-7",
        }
    )

    assert item is not None
    assert item.source_domain == "CRM"
    assert item.source_object_ref == "oportunidad:OP-9"
    assert item.priority_band is PriorityBand.ALTA
    assert item.impact == "monto_estimado:250000"
    assert "CRM_SLA_PROXIMO" in item.priority_score_explanation


def test_e3b_adapter_fails_closed_without_source_identity():
    assert adapt_operational_task({"estado_sla": "VENCIDA"}) is None
    assert adapt_crm_opportunity({"EstatusSLA": "VENCIDO"}) is None


def test_e3b_aggregator_is_cross_domain_deterministic_and_read_only():
    critical = adapt_operational_task(
        {
            "id": "T-2",
            "estado_sla": "ESCALADA",
            "fecha_limite": "2026-09-19T07:00:00Z",
        }
    )
    crm = adapt_crm_opportunity(
        {
            "OportunidadID": "OP-1",
            "EstatusSLA": "PROXIMO",
            "MontoEstimado": 1000,
        }
    )
    medium = adapt_operational_task(
        {
            "id": "T-3",
            "prioridad": "MEDIA",
            "fecha_limite": "2026-09-20T07:00:00Z",
        }
    )

    result = aggregate_priorities([medium, crm, critical])

    assert result.total == 3
    assert result.domains == ("CRM", "OPERATIVO")
    assert [item.source_object_ref for item in result.items] == [
        "tarea:T-2",
        "oportunidad:OP-1",
        "tarea:T-3",
    ]


def test_e3b_same_band_uses_due_date_not_global_numeric_weights():
    later = adapt_operational_task(
        {
            "id": "T-LATE",
            "prioridad": "ALTA",
            "fecha_limite": "2026-09-20T12:00:00Z",
        }
    )
    sooner = adapt_operational_task(
        {
            "id": "T-SOON",
            "prioridad": "ALTA",
            "fecha_limite": "2026-09-19T12:00:00Z",
        }
    )

    result = aggregate_priorities([later, sooner])

    assert [item.source_object_ref for item in result.items] == [
        "tarea:T-SOON",
        "tarea:T-LATE",
    ]


def test_e3b_aggregate_propagates_stale_without_hiding_priority():
    stale = adapt_operational_task(
        {
            "id": "T-STALE",
            "estado_sla": "VENCIDA",
            "stale": True,
        }
    )

    result = aggregate_priorities([stale])

    assert result.stale is True
    assert result.items[0].priority_band is PriorityBand.CRITICA
